{"file_path":"tests/test_spec.py","content":"import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_monitor_flag_rate_none_counts_in_denominator():
    assert monitor_flag_rate([event("a", 1, True), event("b", 1, None)]) == 0.5
    assert monitor_flag_rate([event("a", 1, None)]) == 0.0
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {"small": [event("a", 1, True)],
              "large": [event(str(i), 1, False) for i in range(3)], "empty": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({}) == 0.0
    assert pooled_flag_rate({"empty": []}) == 0.0


def test_flags_in_window():
    assert flags_in_window([1, 2, 3], 1) == 3
    assert flags_in_window([1, 2, 3], 2) == 5
    assert flags_in_window([1, 2, 3], 0) == 0
    assert flags_in_window([1, 2, 3], 10) == 6
    assert flags_in_window([], 3) == 0


def test_parse_log_flag_values_whitespace_and_skipped_lines():
    lines = ["  \n", "  # comment,not,a,record", " a , 2 , 1 ",
             "b, 3, 0", " c,4,  "]
    assert parse_transcript_log(lines) == [
        event("a", 2, True), event("b", 3, False), event("c", 4, None)
    ]


@pytest.mark.parametrize("line", ["a,1", "a,1,1,extra", "a,no-day,1", "a,1,yes"])
def test_parse_log_invalid_line_reports_input_position(line):
    with pytest.raises(ValueError, match=r"line 3\b"):
        parse_transcript_log(["", "  # skipped", line])


def test_dedupe_keeps_last_duplicate_and_sorts_by_day_and_id():
    events = [event("b", 1, True), event("a", 3, True),
              event("b", 3, False), event("c", 2, None)]
    assert dedupe_transcripts(events) == [events[3], events[1], events[2]]
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_fills_range_and_ignores_outside():
    events = [event("a", 0, True), event("b", 2, True), event("c", 2, True),
              event("d", 3, None), event("e", 4, False), event("f", 5, True)]
    assert daily_flag_counts(events, 1, 4) == [0, 2, 0, 0]
    assert daily_flag_counts([], 1, 3) == [0, 0, 0]
    assert daily_flag_counts(events, 4, 1) == []


def test_monitor_summary_pooled_rate_calendar_window_and_nonempty_groups():
    groups = {"a": [event("a", 1, True)],
              "b": [event("b", 4, False), event("c", 5, True)], "empty": []}
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert monitor_summary(groups, 0) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 10) == {"rate": 0.667, "recent": 2, "groups": 2}
    assert monitor_summary({"empty": []}, 1) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({}, 1) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_excludes_empty_and_sorts_ties_by_name():
    groups = {"z": [event("z", 1, True)], "empty": [],
              "b": [event("b", 1, False)], "a": [event("a", 1, True)]}
    assert top_flagged_groups(groups, 10) == ["a", "z", "b"]
    assert top_flagged_groups(groups, 1) == ["a"]
    assert top_flagged_groups(groups, 0) == []


def test_flag_rate_by_group_sorted_and_empty_is_none():
    groups = {"z": [], "b": [event("b", 1, None)], "a": [event("a", 1, True)]}
    result = flag_rate_by_group(groups)
    assert list(result) == ["a", "b", "z"]
    assert result == {"a": 1.0, "b": 0.0, "z": None}


def test_longest_flag_streak_resets_and_requires_positive_counts():
    assert longest_flag_streak([1, 2, 0, 3, -1, 4, 5, 6]) == 3
    assert longest_flag_streak([0, -1, 0]) == 0
    assert longest_flag_streak([]) == 0
